const e=$json||{}; const supported=new Set(['viryaos.merch.reorder_requested','viryaos.merch.bundle_requested','viryaos.content.artifact_requested','viryaos.show.task_attention_required','viryaos.ops.status_changed']);
if(e.version!==1||!supported.has(String(e.type||''))) throw new Error('Unsupported VIRYA OS team action');
const d=e.data||{}; const action_id=String(d.action_id||'').trim(); if(!action_id) throw new Error('Missing action_id');
const clean=v=>String(v??'').replace(/[
	]+/g,' ').trim(); let content='';
if(e.type==='viryaos.merch.reorder_requested'){
  content=`📦 **VIRYA OS · RESTOCK**
Wariant: \`${clean(d.variant_id)}\`
Ilość: **${Number(d.quantity||0)} szt.**

To jest gotowe zadanie operacyjne — potwierdź zamówienie/uzupełnienie u dostawcy.`;
}else if(e.type==='viryaos.merch.bundle_requested'){
  const price=(Number(d.bundle_price_minor||0)/100).toFixed(2); const affinity=(Number(d.affinity_basis_points||0)/100).toFixed(1);
  content=`🧩 **VIRYA OS · BUNDLE DO WDROŻENIA**
Produkt A: \`${clean(d.product_a)}\`
Produkt B: \`${clean(d.product_b)}\`
Cena bundle: **${price} PLN**
Affinity: **${affinity}%**

Parametry są już policzone przez CrowdRelay — executor ich nie zmienia.`;
}else if(e.type==='viryaos.show.task_attention_required'){
  content=`🚨 **VIRYA OS · SHOW OPS — WYMAGA UWAGI**
Event: \`${clean(d.event_id)}\`
Zadanie: **${clean(d.task).replace(/_/g,' ')}**

Sprawdź i domknij przed kolejnym cyklem operacyjnym.`;
}else{
  const title=clean(d.source_title)||'VIRYA'; const artifact=clean(d.artifact)||'content'; const m=(d.source_metadata&&typeof d.source_metadata==='object')?d.source_metadata:{};
  const preferred=['city','venue','starts_at','release_at','date','url','ticket_url','destination_url']; const facts=[];
  for(const key of preferred){if(m[key]!=null&&typeof m[key]!=='object'){const v=clean(m[key]);if(v)facts.push(`${key.replace(/_/g,' ')}: ${v}`)}}
  if(!facts.length){for(const [k,v] of Object.entries(m).sort(([a],[b])=>a.localeCompare(b))){if(facts.length>=4)break;if(v!=null&&typeof v!=='object'){const cv=clean(v);if(cv)facts.push(`${k.replace(/_/g,' ')}: ${cv}`)}}}
  const factline=facts.slice(0,4).join(' · '); let draft='';
  if(artifact==='social_story') draft=`${title}${factline?`
${factline}`:''}

VIRYA · złap sygnał: https://virya.music/`;
  else if(artifact==='social_feed') draft=`VIRYA · ${title}${factline?`

${factline}`:''}

Więcej: https://virya.music/`;
  else if(artifact==='signal_push') draft=`VIRYA · ${title}${factline?` — ${factline}`:''}`;
  else if(artifact==='newsletter_block') draft=`**${title}**${factline?`
${factline}`:''}

Aktualny sygnał: https://virya.music/`;
  else if(artifact==='press_hook') draft=`VIRYA — ${title}.${factline?` ${factline}.`:''} Materiały prasowe: https://virya.music/pl/epk/`;
  else if(artifact==='post_show_recap') draft=`VIRYA · ${title}${factline?`
${factline}`:''}

Dzięki za wspólny sygnał.`;
  else draft=`VIRYA · ${title}${factline?`
${factline}`:''}`;
  content=`✍️ **VIRYA OS · GOTOWY ARTIFACT: ${artifact.replace(/_/g,' ').toUpperCase()}**
Template: \`${clean(d.template_key)}\`

${draft}`;
}
return [{json:{event_id:String(e.id||''),event_type:String(e.type),action_id,discord_message:content.slice(0,1950)}}];

const src=$('Build deterministic team action').item.json||{}; const r=$json||{}; const disposition=String(r.disposition||'');
if(disposition==='already_succeeded') return [];
if(disposition!=='claimed'||!r.claim_token) throw new Error(`Provider execution ${disposition||'unclaimed'}; fail closed to prevent duplicate external side effects`);
return [{json:{...src,claim_token:String(r.claim_token),attempt_number:Number(r.attempt_number||1)}}];
